def topic(title,children=None,note=None,key=''):
    n={'id':hashlib.sha1((key+title).encode()).hexdigest()[:26],'class':'topic','title':title}
    if children:n['children']={'attached':children}
    if note:n['notes']={'plain':{'content':note}}
    return n
